import functools, time
def retry(n=3, delay=1):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            for i in range(n):
                try: return fn(*a, **kw)
                except Exception:
                    if i == n - 1: raise
                    time.sleep(delay * 2 ** i)
        return wrapper
    return deco

